    "html": "<pre><code>&quot;&quot;&quot;Simple Factory: choose an animal, then use the object it creates.&quot;&quot;&quot;\n\n\nclass Animal:\n    def speak(self):\n        raise NotImplementedError(&quot;Each animal must define speak()&quot;)\n\n\nclass Dog(Animal):\n    def speak(self):\n        return &quot;Woof!&quot;\n\n\nclass Cat(Animal):\n    def speak(self):\n        return &quot;Meow!&quot;\n\n\ndef create_animal(choice):  # Factory: chooses which class to instantiate\n    if choice == &quot;dog&quot;:\n        return Dog()\n    if choice == &quot;cat&quot;:\n        return Cat()\n    raise ValueError(&quot;Please choose dog or cat&quot;)\n\n\nif __name__ == &quot;__main__&quot;:\n    animal = create_animal(&quot;dog&quot;)\n    print(animal.speak())\n\n    animal = create_animal(&quot;cat&quot;)\n    print(animal.speak())\n<\/code><\/pre>",
    "text": "\"\"\"Simple Factory: choose an animal, then use the object it creates.\"\"\"\n\n\nclass Animal:\n    def speak(self):\n        raise NotImplementedError(\"Each animal must define speak()\")\n\n\nclass Dog(Animal):\n    def speak(self):\n        return \"Woof!\"\n\n\nclass Cat(Animal):\n    def speak(self):\n        return \"Meow!\"\n\n\ndef create_animal(choice):  # Factory: chooses which class to instantiate\n    if choice == \"dog\":\n        return Dog()\n    if choice == \"cat\":\n        return Cat()\n    raise ValueError(\"Please choose dog or cat\")\n\n\nif __name__ == \"__main__\":\n    animal = create_animal(\"dog\")\n    print(animal.speak())\n\n    animal = create_animal(\"cat\")\n    print(animal.speak())\n"
