    "html": "<pre><code>&quot;&quot;&quot;Adapter: turn an API response into the name our app expects.&quot;&quot;&quot;\n\n\nclass UserAPI:\n    def get_user(self):\n        # Simulated API response: no internet or API key needed.\n        return {&quot;first_name&quot;: &quot;Alex&quot;, &quot;last_name&quot;: &quot;Pham&quot;}\n\n\nclass UserAdapter:\n    def __init__(self, api):\n        self.api = api\n\n    def get_name(self):\n        user = self.api.get_user()\n        return user[&quot;first_name&quot;] + &quot; &quot; + user[&quot;last_name&quot;]\n\n\ndef show_name(user):  # Our app expects get_name().\n    print(user.get_name())\n\n\nif __name__ == &quot;__main__&quot;:\n    api = UserAPI()\n    user = UserAdapter(api)\n    show_name(user)\n<\/code><\/pre>",
    "text": "\"\"\"Adapter: turn an API response into the name our app expects.\"\"\"\n\n\nclass UserAPI:\n    def get_user(self):\n        # Simulated API response: no internet or API key needed.\n        return {\"first_name\": \"Alex\", \"last_name\": \"Pham\"}\n\n\nclass UserAdapter:\n    def __init__(self, api):\n        self.api = api\n\n    def get_name(self):\n        user = self.api.get_user()\n        return user[\"first_name\"] + \" \" + user[\"last_name\"]\n\n\ndef show_name(user):  # Our app expects get_name().\n    print(user.get_name())\n\n\nif __name__ == \"__main__\":\n    api = UserAPI()\n    user = UserAdapter(api)\n    show_name(user)\n"
